// Sanitärplanung structured by the SIA 108:2014 phases. Checklist items paraphrase the requirements of
// SVGW W3:2013 with the Ergänzungen W3/E1–E4, SIA 385/1:2020, SIA 385/2:2015 and SN 592000:2024 (Liegenschafts-
// entwässerung); `ref` names the clause to look up. Items whose `when` fails stay visible, marked as not applicable.

import type { L10n, PlanChecklistItem } from "@/lib/planning";

import type { SanitaryParams } from "./plan-schema";

export type SanitaryChecklistItem = PlanChecklistItem<SanitaryParams>;
export type SanitaryPhaseSection = { kind: "checklist"; key: string; title: L10n; items: SanitaryChecklistItem[] };
export type SanitaryPhase = { code: string; sia108: string; title: L10n; goal: L10n; sections: SanitaryPhaseSection[] };

type P = SanitaryParams;
type Cond = (p: P) => boolean;

const i = (id: string, ref: string, de: string, fr: string, it: string, when?: Cond): SanitaryChecklistItem => ({ id, ref, text: { de, fr, it }, when });
const list = (key: string, title: L10n, items: SanitaryChecklistItem[]): SanitaryPhaseSection => ({ kind: "checklist", key, title, items });
const t = (de: string, fr: string, it: string): L10n => ({ de, fr, it });

const water: Cond = (p) => p.scope.includes("drinkingWater");
/** Trinkwasser item, optionally limited further. */
const w = (cond?: Cond): Cond => (p) => water(p) && (!cond || cond(p));
const multi: Cond = (p) => p.buildingType !== "efh";
const efh: Cond = (p) => p.buildingType === "efh";
const nonRes: Cond = (p) => p.buildingType === "nonResidential";
const sensitive: Cond = (p) => p.use === "sensitive";
const renovation: Cond = (p) => p.construction === "renovation";
const warm: Cond = (p) => p.warmKeeping !== "none";
const circ: Cond = (p) => p.warmKeeping === "circulation";
const storage: Cond = (p) => p.heater === "storage";
const hp: Cond = (p) => p.heatSource === "heatPump";
const solar: Cond = (p) => p.heatSource === "solar";
const renewable: Cond = (p) => hp(p) || solar(p);
const central: Cond = (p) => p.dhw !== "decentral";
const sewage: Cond = (p) => p.scope.includes("wastewater");
const rain: Cond = (p) => p.scope.includes("rainwater");
const drain: Cond = (p) => sewage(p) || rain(p);
/** Entwässerung item, optionally limited further. */
const d = (cond?: Cond): Cond => (p) => drain(p) && (!cond || cond(p));
const lift: Cond = (p) => p.liftingStation;
const below: Cond = (p) => p.belowBackflowLevel;
const infil: Cond = (p) => p.infiltration;
const flat: Cond = (p) => p.flatRoof;
const grease: Cond = (p) => p.separators.includes("grease");
const oil: Cond = (p) => p.separators.includes("oil");
const separators: Cond = (p) => p.separators.length > 0;
const all = (...conds: Cond[]): Cond => (p) => conds.every((c) => c(p));

